/**
 * @packageDocumentation
 * Pingram Node SDK
 *
 * A fully typed TypeScript client for the Pingram API (formerly NotificationAPI).
 *
 * ## Installation
 *
 * ```bash
 * npm install pingram
 * ```
 *
 * ## Authentication
 *
 * The SDK supports API Key authentication:
 * - **API Key** (Bearer) - Server-side project auth using `pingram_sk_...` keys
 *
 * ## Usage
 *
 * ```typescript
 * import { Pingram } from 'pingram';
 *
 * // Initialize with API key
 * const client = new Pingram({
 *   apiKey: 'pingram_sk_...'
 * });
 *
 * // Get a user
 * const user = await client.user.getUser('user456');
 *
 * // Send a notification
 * await client.send({
 *   type: 'welcome_email',
 *   to: {
 *     id: 'user456',
 *     email: 'user@example.com'
 *   }
 * });
 * ```
 */
